from __future__ import annotations

import time

from pytest_bdd import parsers, then
from amtaf.drivers.hardware import HardwareDriver


@then(
    parsers.parse(
        "the device config file has syslog server set to "
        "{ip} within {seconds:d} seconds"
    )
)
def device_config_has_syslog_server(
    device: HardwareDriver, ip: str, seconds: int
) -> None:
    "Poll the device config until syslog_server equals the expected value."
    deadline = time.monotonic() + seconds
    actual: str | None = None
    while time.monotonic() < deadline:
        actual = device.read_config().get("syslog_server")
        if actual == ip:
            return
        time.sleep(1)
    raise AssertionError(f"syslog_server is {actual!r}, expected {ip!r}")
